#!/usr/bin/env python3

"""
Test script to reproduce the annotated types serialization strategy issue.
"""

from dataclasses import dataclass
from typing import Annotated, TypeAlias
from mashumaro import DataClassDictMixin


# Define annotated types
PositiveInt: TypeAlias = Annotated[int, "PositiveInt"]
NegativeInt: TypeAlias = Annotated[int, "NegativeInt"]


def deserialize_positive_int(value):
    if value < 0:
        raise ValueError("value < 0")
    return value


def deserialize_negative_int(value):
    if value >= 0:
        raise ValueError("value >= 0")
    return value


def serialize_positive_int(value):
    if value < 0:
        raise ValueError("value < 0")
    return value


def serialize_negative_int(value):
    if value >= 0:
        raise ValueError("value >= 0")
    return value


@dataclass
class MyClass(DataClassDictMixin):
    positive_int: PositiveInt
    negative_int: NegativeInt

    class Config:
        serialization_strategy = {
            PositiveInt: {
                "deserialize": deserialize_positive_int,
                "serialize": serialize_positive_int,
            },
            NegativeInt: {
                "deserialize": deserialize_negative_int,
                "serialize": serialize_negative_int,
            }
        }


def test_basic_functionality():
    """Test that basic functionality works."""
    print("Testing basic functionality...")

    # Test valid values
    try:
        obj = MyClass(positive_int=5, negative_int=-3)
        print(f"Created object: {obj}")

        # Test serialization
        serialized = obj.to_dict()
        print(f"Serialized: {serialized}")

        # Test deserialization  
        deserialized = MyClass.from_dict({"positive_int": 10, "negative_int": -7})
        print(f"Deserialized: {deserialized}")

        print("Basic functionality test PASSED")
        return True

    except Exception as e:
        print(f"Basic functionality test FAILED: {e}")
        return False


def test_validation_enforcement():
    """Test that custom validation is enforced."""
    print("\nTesting validation enforcement...")

    # Test invalid positive int (should fail)
    try:
        obj = MyClass.from_dict({"positive_int": -5, "negative_int": -3})
        print(f"ERROR: Should have failed validation but got: {obj}")
        return False
    except ValueError as e:
        print(f"Correctly caught validation error for negative positive_int: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
        return False

    # Test invalid negative int (should fail)
    try:
        obj = MyClass.from_dict({"positive_int": 5, "negative_int": 3})
        print(f"ERROR: Should have failed validation but got: {obj}")
        return False
    except ValueError as e:
        print(f"Correctly caught validation error for positive negative_int: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
        return False

    print("Validation enforcement test PASSED")
    return True


def test_serialization_validation():
    """Test that serialization validation is enforced."""
    print("\nTesting serialization validation...")

    # Test invalid positive int serialization (should fail)
    try:
        obj = MyClass(positive_int=-5, negative_int=-3)
        serialized = obj.to_dict()
        print(f"ERROR: Should have failed serialization validation but got: {serialized}")
        return False
    except ValueError as e:
        print(f"Correctly caught validation error for negative positive_int serialization: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
        return False

    # Test invalid negative int serialization (should fail)
    try:
        obj = MyClass(positive_int=5, negative_int=3)
        serialized = obj.to_dict()
