#!/usr/bin/env python3

"""
Comprehensive test for annotated types serialization strategy support.
"""

from dataclasses import dataclass
from typing import Annotated, List, Optional
from typing_extensions import TypeAlias
from mashumaro import DataClassDictMixin


# Define various annotated types
PositiveInt: TypeAlias = Annotated[int, "PositiveInt"]
NegativeInt: TypeAlias = Annotated[int, "NegativeInt"]
NonEmptyString: TypeAlias = Annotated[str, "NonEmptyString"]
EmailStr: TypeAlias = Annotated[str, "EmailStr"]


def deserialize_positive_int(value):
    if not isinstance(value, int) or value <= 0:
        raise ValueError("Positive integer required")
    return value


def serialize_positive_int(value):
    if not isinstance(value, int) or value <= 0:
        raise ValueError("Positive integer required")
    return value


def deserialize_negative_int(value):
    if not isinstance(value, int) or value >= 0:
        raise ValueError("Negative integer required")
    return value


def serialize_negative_int(value):
    if not isinstance(value, int) or value >= 0:
        raise ValueError("Negative integer required")
    return value


def deserialize_non_empty_string(value):
    if not isinstance(value, str) or len(value.strip()) == 0:
        raise ValueError("Non-empty string required")
    return value.strip()


def serialize_non_empty_string(value):
    if not isinstance(value, str) or len(value.strip()) == 0:
        raise ValueError("Non-empty string required")
    return value.strip()


@dataclass
class ComplexClass(DataClassDictMixin):
    pos_int: PositiveInt
    neg_int: NegativeInt
    name: NonEmptyString
    optional_email: Optional[EmailStr] = None
    int_list: List[PositiveInt] = None

    class Config:
        serialization_strategy = {
            PositiveInt: {
                "deserialize": deserialize_positive_int,
                "serialize": serialize_positive_int,
            },
            NegativeInt: {
                "deserialize": deserialize_negative_int,
                "serialize": serialize_negative_int,
            },
            NonEmptyString: {
                "deserialize": deserialize_non_empty_string,
                "serialize": serialize_non_empty_string,
            },
            EmailStr: {
                "deserialize": lambda x: x.lower() if x else None,
                "serialize": lambda x: x.upper() if x else None,
            }
        }


def test_complex_class():
    """Test complex class with multiple annotated types."""
    print("Testing complex class...")

    # Test valid creation and serialization
    obj = ComplexClass(
        pos_int=5,
        neg_int=-3,
        name="John Doe",
        optional_email="john@example.com",
        int_list=[1, 2, 3]
    )
    print(f"Created: {obj}")

    # Test serialization
    serialized = obj.to_dict()
    print(f"Serialized: {serialized}")
    expected_serialized = {
        'pos_int': 5,
        'neg_int': -3,
        'name': 'John Doe',
        'optional_email': 'JOHN@EXAMPLE.COM',
        'int_list': [1, 2, 3]
    }
    assert serialized == expected_serialized, f"Expected {expected_serialized}, got {serialized}"

    # Test deserialization
    data = {
        'pos_int': 10,
        'neg_int': -7,
        'name': '  Jane Smith  ',
        'optional_email': 'JANE@EXAMPLE.COM',
        'int_list': [4, 5, 6]
    }
    deserialized = ComplexClass.from_dict(data)
    print(f"Deserialized: {deserialized}")

    # Check that trimming worked
    assert deserialized.name == "Jane Smith"
    assert deserialized.optional_email == "jane@example.com"

    # Test validation on serialization
    try:
